/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface DocumentSourcePage {
  /** 1-based page number as printed in the document. */
  number: number
  /** Extracted page text. Blank lines separate paragraphs. */
  text: string
}

export interface DocumentSource {
  /** Stable id, for example the AI SDK `sourceId`. */
  id?: string
  title: string
  filename?: string
  mediaType?: string
  /** Total pages in the file, when more than the pages you pass. */
  pageCount?: number
  /** Extracted text per page. Pass only the pages you have; the rest show as not loaded. */
  pages?: DocumentSourcePage[]
  /** Link to the original file. Adds an Open original action. */
  url?: string
}

/** The passage a citation points at. */
export interface DocumentHighlight {
  page: number
  /** Exact text to highlight on that page. Matched case-insensitively. */
  quote: string
}

export interface DocumentViewerProps extends Omit<React.ComponentProps<"div">, "children"> {
  document: DocumentSource
  /** The page in view. Controlled with `onPageChange`, or starts at the highlight. */
  page?: number
  defaultPage?: number
  onPageChange?: (page: number) => void
  highlight?: DocumentHighlight
  loading?: boolean
  /** Shows the error state. Say how to fix it. */
  error?: React.ReactNode
  onRetry?: () => void
  /** Shows a close button in the header. */
  onClose?: () => void
  /** Header title element, for example a dialog title. Defaults to a plain heading. */
  renderTitle?: (title: React.ReactNode) => React.ReactNode
}

interface UseChatcnResearchTocOptions {
  /** Section ids in document order. */
  ids: string[]
  /** Finds the element for an id. Defaults to `document.getElementById`. */
  getElement?: (id: string) => HTMLElement | null
  /**
   * Where the reading line sits, as a fraction of the scroll viewport from its top. A section is
   * active once its heading has passed this line. Defaults to 0.2.
   */
  offset?: number
  /** Turn tracking off, for example while the table of contents is hidden. */
  enabled?: boolean
}

interface UseChatcnResearchTocResult {
  /** The section the reader is in. */
  activeId: string | undefined
  /**
   * Mark a section active right away, for example after a table of contents click, so the
   * highlight does not lag behind a smooth scroll.
   */
  setActiveId: (id: string) => void
}

/** Nearest ancestor that scrolls vertically, or `null` for the window. */
function getChatcnScrollParent(el: HTMLElement | null): HTMLElement | null {
  let node = el?.parentElement ?? null
  while (node && node !== document.body && node !== document.documentElement) {
    const { overflowY } = getComputedStyle(node)
    if (overflowY === "auto" || overflowY === "scroll") return node
    node = node.parentElement
  }
  return null
}

/**
 * Scroll spy for a long report: returns the id of the section whose heading most recently passed
 * the reading line, in the window or in whichever ancestor scrolls. At the very bottom the last
 * section wins, so a short closing section can still become active.
 *
 * Reads layout once per animation frame while scrolling and never writes to the DOM.
 */
function useChatcnResearchToc({
  ids,
  getElement,
  offset = 0.2,
  enabled = true,
}: UseChatcnResearchTocOptions): UseChatcnResearchTocResult {
  const [activeId, setActive] = React.useState<string | undefined>(ids[0])
  const lock = React.useRef<{ id: string; until: number } | null>(null)
  const key = ids.join("\n")
  const getRef = React.useRef(getElement)
  getRef.current = getElement

  React.useEffect(() => {
    if (!enabled || ids.length === 0) return
    const find = (id: string) => getRef.current?.(id) ?? document.getElementById(id)
    const first = find(ids[0] as string)
    const root = getChatcnScrollParent(first)
    const target: HTMLElement | Window = root ?? window
    let frame = 0

    const measure = () => {
      frame = 0
      // A table of contents click scrolls smoothly; hold its choice until the scroll settles.
      if (lock.current && performance.now() < lock.current.until) return
      lock.current = null
      const top = root ? root.getBoundingClientRect().top : 0
      const height = root ? root.clientHeight : window.innerHeight
      const line = top + height * offset
      const scrolled = root
        ? root.scrollTop + root.clientHeight >= root.scrollHeight - 2
        : window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 2
      let next = ids[0]
      if (scrolled) next = ids[ids.length - 1]
      else {
        for (const id of ids) {
          const el = find(id)
          if (!el) continue
          if (el.getBoundingClientRect().top <= line) next = id
          else break
        }
      }
      setActive((prev) => (prev === next ? prev : next))
    }
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    measure()
    target.addEventListener("scroll", onScroll, { passive: true })
    window.addEventListener("resize", onScroll)
    return () => {
      target.removeEventListener("scroll", onScroll)
      window.removeEventListener("resize", onScroll)
      if (frame) cancelAnimationFrame(frame)
    }
  }, [key, offset, enabled])

  const setActiveId = React.useCallback((id: string) => {
    lock.current = { id, until: performance.now() + 900 }
    setActive(id)
  }, [])

  return { activeId: activeId && ids.includes(activeId) ? activeId : ids[0], setActiveId }
}

const prefersReducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

