/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function splitParagraphs(text: string) {
  return text
    .split(/\n\s*\n/)
    .map((p) => p.replace(/\s*\n\s*/g, " ").trim())
    .filter(Boolean)
}

function findQuote(paragraph: string, quote: string) {
  const at = paragraph.toLowerCase().indexOf(quote.toLowerCase().trim())
  return at < 0 ? undefined : { at, length: quote.trim().length }
}

/* -------------------------------------------------------------------------------------------------
 * Page sheet
 * -----------------------------------------------------------------------------------------------*/

function DocumentPage({
  page,
  domId,
  quote,
  markRef,
}: {
  page: DocumentSourcePage
  domId: string
  quote?: string
  markRef: React.Ref<HTMLElement>
}) {
  const paragraphs = splitParagraphs(page.text)
  let found = false
  return (
    <section
      id={domId}
      data-slot="document-page"
      data-page={page.number}
      aria-label={`Page ${page.number}`}
      className={cn(
        "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) rounded-(--chatcn-radius-md) relative mx-auto w-full max-w-[44rem] scroll-mt-4",
        "px-6 pt-8 pb-12 sm:px-10 sm:pt-10",
        "forced-colors:outline-1 forced-colors:outline-solid",
      )}
    >
      <div className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg-muted) flex flex-col gap-3.5 leading-6">
        {paragraphs.map((p, i) => {
          const hit = quote && !found ? findQuote(p, quote) : undefined
          if (hit) found = true
          // Short lines without a full stop are headings in extracted text.
          const heading = !hit && p.length < 48 && !/[.:;,?!]$/.test(p)
          return (
            <p
              key={i}
              data-cited={hit ? "" : undefined}
              className={cn(
                "relative text-pretty",
                heading && "text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) mt-2 font-semibold first:mt-0",
                // A rule in the margin points at the cited paragraph from a distance.
                hit &&
                  "text-(color:--chatcn-fg) before:bg-(color:--chatcn-fg) before:absolute before:inset-y-0.5 before:-start-3.5 before:w-0.5 before:rounded-full sm:before:-start-5",
              )}
            >
              {hit ? (
                <>
                  {p.slice(0, hit.at)}
                  <mark
                    ref={markRef}
                    data-slot="document-highlight"
                    className="bg-(color:--chatcn-alpha-400) text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) box-decoration-clone px-0.5 py-px"
                  >
                    {p.slice(hit.at, hit.at + hit.length)}
                  </mark>
                  {p.slice(hit.at + hit.length)}
                </>
              ) : (
                p
              )}
            </p>
          )
        })}
      </div>
      <span
        aria-hidden="true"
        className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) absolute inset-x-0 bottom-4 text-center tabular-nums"
      >
        {page.number}
      </span>
    </section>
  )
}

/* -------------------------------------------------------------------------------------------------
 * DocumentViewer
 * -----------------------------------------------------------------------------------------------*/

/**
 * Reads a document source: page sheets on an inset canvas, the cited passage highlighted with a
 * rule in the margin and scrolled to the middle of the view, and page navigation that follows
 * the reader. Works in a dialog (see `SourceDocument`) or a side panel.
 */
export function DocumentViewer({
  document: doc,
  page: pageProp,
  defaultPage,
  onPageChange,
  highlight,
  loading = false,
  error,
  onRetry,
  onClose,
  renderTitle,
  className,
  ...props
}: DocumentViewerProps) {
  const uid = React.useId().replace(/:/g, "")
  const pages = doc.pages ?? []
  const total = doc.pageCount ?? pages.length
  const pageDomId = (n: number) => `${uid}-page-${n}`
  const scrollRef = React.useRef<HTMLElement>(null)
  const markRef = React.useRef<HTMLElement>(null)

  const ids = React.useMemo(() => pages.map((p) => String(p.number)), [pages])
  const { activeId, setActiveId } = useChatcnResearchToc({
    ids,
    getElement: (id) => document.getElementById(pageDomId(Number(id))),
    offset: 0.35,
    enabled: !loading && !error && pages.length > 0,
  })
  const [pageState, setPageState] = React.useState(
    defaultPage ?? highlight?.page ?? pages[0]?.number ?? 1,
  )
  const scrolledPage = activeId ? Number(activeId) : undefined
  const current = pageProp ?? scrolledPage ?? pageState

  // Report scroll-driven page changes once.
  const reported = React.useRef(current)
  React.useEffect(() => {
    if (scrolledPage === undefined || scrolledPage === reported.current) return
    reported.current = scrolledPage
    setPageState(scrolledPage)
    onPageChange?.(scrolledPage)
  }, [scrolledPage, onPageChange])

  const goTo = React.useCallback(
    (n: number, instant: boolean) => {
      const el = document.getElementById(pageDomId(n))
      if (!el) return
      setActiveId(String(n))
      setPageState(n)
      reported.current = n
      onPageChange?.(n)
      el.scrollIntoView({
        behavior: instant || prefersReducedMotion() ? "auto" : "smooth",
        block: "start",
      })
    },
    [setActiveId, onPageChange, uid],
  )

  // Bring the cited passage to the middle of the view. Instant on first show (a dialog is
  // animating in already), smooth when the highlight changes while the viewer is open.
  const first = React.useRef(true)
  const highlightKey = highlight ? `${highlight.page}:${highlight.quote}` : ""
  React.useLayoutEffect(() => {
    if (!highlightKey || loading) return
    const mark = markRef.current
    const target = mark ?? document.getElementById(pageDomId(highlight?.page ?? 1))
    if (!target) return
    const scroller = scrollRef.current ?? getChatcnScrollParent(target)
    const smooth = !first.current && !prefersReducedMotion()
    first.current = false
    if (highlight) {
      setActiveId(String(highlight.page))
      setPageState(highlight.page)
      reported.current = highlight.page
    }
    if (scroller && mark) {
      const sRect = scroller.getBoundingClientRect()
      const mRect = mark.getBoundingClientRect()
      const top = scroller.scrollTop + (mRect.top - sRect.top) - sRect.height / 2 + mRect.height / 2
      scroller.scrollTo({ top: Math.max(0, top), behavior: smooth ? "smooth" : "auto" })
    } else {
      target.scrollIntoView({ block: "start", behavior: smooth ? "smooth" : "auto" })
    }
  }, [highlightKey, loading, pages.length])

  const index = pages.findIndex((p) => p.number === current)
  const prev = index > 0 ? pages[index - 1] : undefined
  const next = index >= 0 && index < pages.length - 1 ? pages[index + 1] : undefined

  const title = (
    <span className="flex min-w-0 flex-col">
      <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) truncate font-medium">{doc.title}</span>
      {doc.filename ? (
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate" dir="ltr">
          {doc.filename}
        </span>
      ) : null}
    </span>
  )

  return (
    <div
      data-slot="document-viewer"
      className={cn("bg-(color:--chatcn-bg-subtle) text-(color:--chatcn-fg) flex min-h-0 min-w-0 flex-col", className)}
      {...props}
    >
      <header className="bg-(color:--chatcn-surface) border-(color:--chatcn-border) flex h-14 shrink-0 items-center gap-3 border-b ps-4 pe-2">
        <FileTextIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
        <div className="min-w-0 flex-1">{renderTitle ? renderTitle(title) : title}</div>
        {pages.length > 0 && !error ? (
          <nav aria-label="Pages" className="flex shrink-0 items-center gap-0.5">
            <Button
              size="icon-sm"
              aria-label="Previous page"
              disabled={!prev}
              onClick={(event) => prev && goTo(prev.number, event.detail === 0)}
              className="pointer-coarse:size-11"
            >
              <ChevronLeftIcon className="rtl:-scale-x-100" />
            </Button>
            <span
              aria-live="polite"
              className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) min-w-[4.5rem] text-center tabular-nums"
            >
              <span className="sr-only">Page </span>
              {current}
              <span className="text-(color:--chatcn-fg-subtle)"> of {total}</span>
            </span>
            <Button
              size="icon-sm"
              aria-label="Next page"
              disabled={!next}
              onClick={(event) => next && goTo(next.number, event.detail === 0)}
              className="pointer-coarse:size-11"
            >
              <ChevronRightIcon className="rtl:-scale-x-100" />
            </Button>
          </nav>
        ) : null}
        {doc.url || onClose ? (
          <span aria-hidden="true" className="bg-(color:--chatcn-border) mx-1 h-5 w-px shrink-0" />
        ) : null}
        {doc.url ? (
          <a
            href={doc.url}
            target="_blank"
            rel="noreferrer"
            aria-label="Open original"
            title="Open original"
            className={cn(
              buttonVariants({ variant: "ghost", size: "icon-sm" }),
              "pointer-coarse:size-11",
            )}
          >
            <ExternalLinkIcon />
          </a>
        ) : null}
        {onClose ? (
          <Button
            size="icon-sm"
            aria-label="Close document"
            onClick={onClose}
            className="pointer-coarse:size-11"
          >
            <XIcon />
          </Button>
        ) : null}
      </header>

      <section
        ref={scrollRef}
        // biome-ignore lint/a11y/noNoninteractiveTabindex: the scroll area takes arrow keys for paging
        tabIndex={0}
        aria-label={`${doc.title}, document text`}
        onKeyDown={(event) => {
          if (event.target !== event.currentTarget) return
          const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
          const back = rtl ? "ArrowRight" : "ArrowLeft"
          const fwd = rtl ? "ArrowLeft" : "ArrowRight"
          if (event.key === back && prev) {
            event.preventDefault()
            goTo(prev.number, true)
          } else if (event.key === fwd && next) {
            event.preventDefault()
            goTo(next.number, true)
          }
        }}
        className="chatcn-focus chatcn-scroll min-h-0 flex-1 overflow-y-auto px-3 py-4 outline-none focus-visible:-outline-offset-2 sm:px-6 sm:py-6"
      >
        {error ? (
          <div
            role="alert"
            className="mx-auto flex max-w-sm flex-col items-center gap-2 py-16 text-center"
          >
            <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) mb-1 size-5" />
            <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">
              Could not open {doc.filename ?? doc.title}
            </p>
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{error}</p>
            {onRetry ? (
              <Button size="sm" variant="outline" onClick={onRetry} className="mt-2">
                <RotateCcwIcon />
                Retry
              </Button>
            ) : null}
          </div>
        ) : loading ? (
          <div
            role="status"
            aria-busy="true"
            aria-label="Loading document"
            className="flex flex-col gap-4"
          >
            <DocumentPageSkeleton />
            <DocumentPageSkeleton />
          </div>
        ) : pages.length === 0 ? (
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) py-16 text-center">
            This document has no extracted text. Open the original to read it.
          </p>
        ) : (
          <div className="flex flex-col gap-4">
            {pages.map((page) => (
              <DocumentPage
                key={page.number}
                page={page}
                domId={pageDomId(page.number)}
                quote={highlight?.page === page.number ? highlight.quote : undefined}
                markRef={markRef}
              />
            ))}
          </div>
        )}
      </section>
    </div>
  )
}

export default DocumentViewer

