/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

interface SourceDocumentProps extends Omit<React.ComponentProps<"button">, "children"> {
  document: DocumentSource
  /** Cited page. Shown on the chip and opened in the viewer. */
  page?: number
  /** The cited passage, highlighted in the viewer. Shown as an excerpt on the card. */
  quote?: string
  /** Citation number, when the chip stands for a numbered source. */
  index?: number
  /** Hide the title on the chip, leaving the number and page. Useful for dense answers. */
  hideTitle?: boolean
  /** Marks the chip whose document is showing in your own viewer. */
  active?: boolean
  /** `chip` sits inline in an answer; `card` belongs in a sources list. */
  variant?: "chip" | "card"
  /**
   * `dialog` opens the built-in viewer. `none` only calls `onOpen`, so you can show the
   * `DocumentViewer` in your own side panel.
   */
  viewer?: "dialog" | "none"
  onOpen?: () => void
  /** Loading and error states for the viewer, while the page text is fetched. */
  viewerLoading?: boolean
  viewerError?: React.ReactNode
  onViewerRetry?: () => void
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

function kindLabel(doc: DocumentSource) {
  const ext = doc.filename?.split(".").pop()?.toUpperCase()
  if (ext && ext.length <= 4) return ext
  if (doc.mediaType === "application/pdf") return "PDF"
  return "Document"
}

type DialogProps = React.ComponentProps<typeof DialogPrimitive.Root>

/* -------------------------------------------------------------------------------------------------
 * Motion
 *
 * Scrim and popup share one duration and curve: 220 ms in, 160 ms out, ease-chatcn-out. The popup
 * grows from 0.96 at the center and leaves at 0.98 (exits travel less). Opened or closed from the
 * keyboard, nothing animates: Enter and Esc should feel instant.
 * -----------------------------------------------------------------------------------------------*/

const InstantContext = React.createContext(false)

/** A keyboard Enter on a button arrives as a click with `detail === 0`. */
function isKeyboardEvent(event: Event | undefined) {
  if (!event) return false
  if (typeof KeyboardEvent !== "undefined" && event instanceof KeyboardEvent) return true
  return event.type === "click" && (event as MouseEvent).detail === 0
}

function Dialog({ onOpenChange, ...props }: DialogProps) {
  const [instant, setInstant] = React.useState(false)
  return (
    <InstantContext.Provider value={instant}>
      <DialogPrimitive.Root
        onOpenChange={(open, details) => {
          setInstant(isKeyboardEvent(details.event))
          onOpenChange?.(open, details)
        }}
        {...props}
      />
    </InstantContext.Provider>
  )
}

type DialogSize = "sm" | "md" | "lg" | "xl" | "full"

interface DialogContentProps extends React.ComponentProps<typeof DialogPrimitive.Popup> {
  size?: DialogSize
  /** Render the close button in the corner. On by default. */
  showClose?: boolean
  /** Classes for the scrim behind the popup. */
  backdropClassName?: string
  container?: React.ComponentProps<typeof DialogPrimitive.Portal>["container"]
}

const sizes: Record<DialogSize, string> = {
  sm: "w-[min(24rem,calc(100vw-2rem))]",
  md: "w-[min(32rem,calc(100vw-2rem))]",
  lg: "w-[min(44rem,calc(100vw-2rem))]",
  xl: "w-[min(64rem,calc(100vw-2rem))]",
  full: "h-[calc(100dvh-2rem)] w-[calc(100vw-2rem)]",
}

function DialogContent({
  size = "md",
  showClose = true,
  backdropClassName,
  container,
  className,
  children,
  ...props
}: DialogContentProps) {
  const instant = React.useContext(InstantContext)
  return (
    <DialogPrimitive.Portal container={container}>
      <DialogPrimitive.Backdrop
        data-slot="dialog-backdrop"
        data-dialog-instant={instant ? "" : undefined}
        className={cn(
          "bg-(color:--chatcn-scrim) fixed inset-0 z-50",
          "ease-(--chatcn-ease-out) transition-opacity duration-220",
          "data-[ending-style]:opacity-0 data-[ending-style]:duration-160 data-[starting-style]:opacity-0",
          "data-[dialog-instant]:transition-none",
          backdropClassName,
        )}
      />
      <DialogPrimitive.Popup
        data-slot="dialog-content"
        data-size={size}
        data-dialog-instant={instant ? "" : undefined}
        className={cn(
          "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xl) rounded-(--chatcn-radius-xl) fixed top-1/2 left-1/2 z-50 -translate-x-1/2 -translate-y-1/2",
          "flex max-h-[calc(100dvh-2rem)] origin-center flex-col overflow-hidden outline-none",
          sizes[size],
          "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-220",
          "data-[starting-style]:scale-(--chatcn-enter-scale) data-[starting-style]:opacity-0",
          "data-[ending-style]:scale-(--chatcn-exit-scale) data-[ending-style]:opacity-0 data-[ending-style]:duration-160",
          "motion-reduce:data-[ending-style]:scale-100",
          "data-[dialog-instant]:transition-none",
          // Forced colors strip shadows, so the hairline needs a real outline.
          "forced-colors:outline-1 forced-colors:outline-solid",
          className,
        )}
        {...props}
      >
        {children}
        {showClose ? (
          <DialogPrimitive.Close
            aria-label="Close"
            data-slot="dialog-close"
            className={cn(
              buttonVariants({ variant: "ghost", size: "icon-sm" }),
              "absolute end-3 top-3 pointer-coarse:size-11",
            )}
          >
            <XIcon />
          </DialogPrimitive.Close>
        ) : null}
      </DialogPrimitive.Popup>
    </DialogPrimitive.Portal>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("text-[1rem]/[1.5rem] tracking-[-0.01em] text-(color:--chatcn-fg) pe-8 font-semibold text-balance", className)}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * SourceDocument
 * -----------------------------------------------------------------------------------------------*/

/**
 * A document source with its cited page. Opens the document with the cited passage highlighted
 * and scrolled into view, in a dialog by default or wherever you render `DocumentViewer`.
 */
function SourceDocument({
  document: doc,
  page,
  quote,
  index,
  hideTitle = false,
  active = false,
  variant = "chip",
  viewer = "dialog",
  onOpen,
  viewerLoading,
  viewerError,
  onViewerRetry,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className,
  onClick,
  ...props
}: SourceDocumentProps) {
  const [openState, setOpenState] = React.useState(defaultOpen)
  const open = openProp ?? openState
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const trigger =
    variant === "chip" ? (
      <button
        type="button"
        data-slot="source-document"
        data-variant="chip"
        aria-haspopup={viewer === "dialog" ? "dialog" : undefined}
        aria-pressed={viewer === "none" ? active : undefined}
        data-active={active || undefined}
        onClick={(event) => {
          onClick?.(event)
          if (event.defaultPrevented) return
          onOpen?.()
          if (viewer === "dialog") setOpen(true)
        }}
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-sm) bg-(color:--chatcn-fill) text-(color:--chatcn-fg-muted) relative ms-1 inline-flex h-6 max-w-64 items-center gap-1.5 px-1.5 align-middle",
          // Selected chip: the accent (ink by default) is allowed on selection, so themes recolor it.
          "data-[active]:bg-(color:--chatcn-accent) data-[active]:text-(color:--chatcn-accent-fg) data-[active]:[&_span]:text-(color:--chatcn-accent-fg)",
          "text-[0.75rem]/[1rem] font-medium select-none",
          "ease-(--chatcn-ease-standard) transition-[background-color,color,scale] duration-150",
          "hover:bg-(color:--chatcn-fill-active) hover:text-(color:--chatcn-fg) data-[active]:hover:bg-(color:--chatcn-accent) data-[active]:hover:text-(color:--chatcn-accent-fg) active:scale-(--chatcn-press-scale) active:duration-100",
          "after:absolute after:-inset-1 after:content-[''] pointer-coarse:after:-inset-2.5",
          className,
        )}
        {...props}
      >
        <span className="sr-only">Open </span>
        {index !== undefined ? (
          <span className="text-(color:--chatcn-fg-subtle) tabular-nums">{index}</span>
        ) : (
          <FileTextIcon aria-hidden="true" className="size-3.5 shrink-0" />
        )}
        {/* Spaces keep the accessible name readable; flex layout ignores them. */}{" "}
        {hideTitle ? (
          <span className="sr-only">{doc.title}</span>
        ) : (
          <span className="min-w-0 truncate">{doc.title}</span>
        )}
        {page ? " " : null}
        {page ? (
          <span className="text-(color:--chatcn-fg-subtle) shrink-0 font-normal tabular-nums">
            p.&nbsp;{page}
          </span>
        ) : null}
      </button>
    ) : (
      <button
        type="button"
        data-slot="source-document"
        data-variant="card"
        aria-haspopup={viewer === "dialog" ? "dialog" : undefined}
        onClick={(event) => {
          onClick?.(event)
          if (event.defaultPrevented) return
          onOpen?.()
          if (viewer === "dialog") setOpen(true)
        }}
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-lg) group/doc flex w-full min-w-0 items-start gap-3 p-3 text-start",
          "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) ease-(--chatcn-ease-standard) transition-[background-color,box-shadow] duration-150",
          "hover:bg-(color:--chatcn-fill-hover)",
          className,
        )}
        {...props}
      >
        <span
          aria-hidden="true"
          className="bg-(color:--chatcn-fill) text-(color:--chatcn-fg-subtle) rounded-(--chatcn-radius-sm) grid h-10 min-w-8 shrink-0 place-items-center px-1"
        >
          <span className="text-[0.75rem]/[1rem] font-medium tracking-tight">
            {kindLabel(doc).slice(0, 4)}
          </span>
        </span>
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="flex min-w-0 items-baseline gap-2">
            <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) min-w-0 truncate font-medium">
              {doc.title}
            </span>
            {page ? (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ms-auto shrink-0 tabular-nums">
                Page {page}
              </span>
            ) : null}
          </span>
          {doc.filename ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate" dir="ltr">
              {doc.filename}
              {doc.pageCount ? ` · ${doc.pageCount} ${doc.pageCount === 1 ? "page" : "pages"}` : ""}
            </span>
          ) : null}
          {quote ? (
            // The passage wears the same edge it has in the viewer, so the click lands somewhere
            // you have already seen.
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) border-(color:--chatcn-border-strong) mt-1.5 line-clamp-2 border-s-2 ps-2.5 text-pretty">
              {quote}
            </span>
          ) : null}
        </span>
      </button>
    )

  if (viewer !== "dialog") return trigger

  return (
    <>
      {trigger}
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent
          size="lg"
          showClose={false}
          className="h-[min(48rem,calc(100dvh-2rem))] w-[min(52rem,calc(100vw-2rem))]"
        >
          <DocumentViewer
            className="h-full"
            document={doc}
            highlight={page && quote ? { page, quote } : undefined}
            defaultPage={page}
            loading={viewerLoading}
            error={viewerError}
            onRetry={onViewerRetry}
            onClose={() => setOpen(false)}
            renderTitle={(title) => (
              <DialogTitle render={<div />} className="font-normal">
                {title}
              </DialogTitle>
            )}
          />
        </DialogContent>
      </Dialog>
    </>
  )
}

